head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > E > onchange]<br/>Calendar 컴포넌트에서 선택된 날짜가 변경될 때 발생합니다.",
    "validation" : [
        "Calendar 컴포넌트에서 선택된 날짜가 변경될 때 onchange 이벤트가 발생합니다.",
        "gotoCalendar(), gotoYear(), gotoMonth() 등 API 를 통해 날짜를 변경한 경우에도 onchange 이벤트가 발생합니다.",
        "변경 전/후 값이 동일하면 onchange 이벤트가 발생하지 않습니다.",
        "날짜/연도/월/시간 등 모든 종류의 값 변경에 대해 onchange 이벤트가 발생합니다.",
        "날짜 셀 클릭 시 onchange -> ondateselect -> onviewchange 순서로 이벤트가 발생합니다.",
        "SelectBox 에서 연도/월 변경 시 onchange -> onviewchange -> [onyearselect/onmonthselect] 순서로 이벤트가 발생합니다.",        
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 라벨: 수동 테스트 안내 (validation 5, 6)
    $c.gcm.createLabel('label="[수동 테스트 안내] 날짜 셀 클릭 시: onchange → ondateselect → onviewchange 순서로 발생 / 헤더의 연도/월 SelectBox 변경 시: onchange → onviewchange → [onyearselect/onmonthselect] 순서로 발생"', '', 'label1');

    // calendarValueType: 날짜/연도/월/시간/분/초 변경 모두 검증 가능
    let properties = {
        calendarValueType : "yearMonthDateTimeSec"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange", "ondateselect", "onviewchange", "onyearselect", "onmonthselect"]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 선택일: 2025-11-11
}



// API 호출에 의한 onchange 발생 검증
// case 1: gotoCalendar('20251225')   → 날짜 변경 → onchange 발생 (validation 1, 2)
// case 2: gotoYear(2026)             → 연도 변경 → onchange 발생 (validation 2)
// case 3: gotoMonth(3)               → 월 변경   → onchange 발생 (validation 2)
// case 4: gotoTime(15, 30, 45)       → 시간 변경 → onchange 발생 (validation 4 - 시간 변경)
// case 5: gotoCalendar(현재값)        → 동일 값  → onchange 미발생 (validation 3)
scwin.btn_call_onclick = function (e) {
    let caseId = con_gotoCase.getValue();
    let argDesc = '';

    let beforeValue = target1.getValue();

    if (caseId === '1') {
        argDesc = "gotoCalendar('20251225')";
        wf_body_bottom.getObj("scwin").setReturnValue("[호출] " + argDesc + " / [호출 전 getValue()] '" + beforeValue + "'");
        target1.gotoCalendar('20251225');
    } else if (caseId === '2') {
        argDesc = "gotoYear(2026)";
        wf_body_bottom.getObj("scwin").setReturnValue("[호출] " + argDesc + " / [호출 전 getValue()] '" + beforeValue + "'");
        target1.gotoYear(2026);
    } else if (caseId === '3') {
        argDesc = "gotoMonth(3)";
        wf_body_bottom.getObj("scwin").setReturnValue("[호출] " + argDesc + " / [호출 전 getValue()] '" + beforeValue + "'");
        target1.gotoMonth(3);
    } else if (caseId === '4') {
        argDesc = "gotoTime(15, 30, 45)";
        wf_body_bottom.getObj("scwin").setReturnValue("[호출] " + argDesc + " / [호출 전 getValue()] '" + beforeValue + "'");
        target1.gotoTime(15, 30, 45);
    } else if (caseId === '5') {
        // 현재 값과 동일한 값으로 gotoCalendar 호출 → onchange 미발생
        let sameDate = beforeValue.substring(0, 8);
        argDesc = "gotoCalendar('" + sameDate + "') (현재 값과 동일)";
        wf_body_bottom.getObj("scwin").setReturnValue("[호출] " + argDesc + " / [호출 전 getValue()] '" + beforeValue + "'");
        target1.gotoCalendar(sameDate);
    }

    let afterValue = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("[호출 후 getValue()] '" + afterValue + "' / [값 변경 여부] " + (beforeValue !== afterValue));
};



// 선택된 날짜가 변경될 때 발생 (validation 1, 2, 3, 4)
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생]");
};



// 날짜 셀 클릭 시 onchange -> ondateselect -> onviewchange 순서 (validation 5)
scwin.target1_ondateselect = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[ondateselect 발생]");
};



// 사용자의 조작에 의해 선택일이 변경된 경우 처리 (validation 5, 6, 7)
scwin.target1_onviewchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onviewchange 발생]");
};



// SelectBox 에서 연도 변경 시 (validation 6)
scwin.target1_onyearselect = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onyearselect 발생]");
};



// SelectBox 에서 월 변경 시 (validation 6)
scwin.target1_onmonthselect = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onmonthselect 발생]");
};
